/* ==========================================================================
   DSML Icons Stylesheet
   Self-contained with Base64 Data URIs to support file:/// protocol
   ========================================================================== */

/* Base icon behavior using CSS Masks */
.ml-icon, [class^="ml-icon-"], [class*=" ml-icon-"] {
  --ml-icon-size: 1.5rem; /* 24px default */
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: var(--ml-icon-size);
  height: var(--ml-icon-size);
  vertical-align: middle;
  position: relative;
}

.ml-icon::before, [class^="ml-icon-"]::before, [class*=" ml-icon-"]::before {
  content: "";
  display: inline-block;
  width: 100%;
  height: 100%;
  background-color: currentColor;
  -webkit-mask-size: 100% 100%;
  mask-size: 100% 100%;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-position: center;
}

/* Sizing variants */
.ml-icon--xs {
  --ml-icon-size: 0.75rem !important; /* 12px */
}
.ml-icon--sm {
  --ml-icon-size: 1rem !important; /* 16px */
}
.ml-icon--md {
  --ml-icon-size: 1.5rem !important; /* 24px */
}
.ml-icon--lg {
  --ml-icon-size: 2rem !important; /* 32px */
}

